// iOS entry point: hand the main thread to the Rust game. `start_app` is generated by
// `space3d::main!` in mobile/src/lib.rs and never returns (winit runs UIApplicationMain).
extern void start_app(void);

int main(int argc, char *argv[]) {
    (void)argc;
    (void)argv;
    start_app();
    return 0;
}
